head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > E > onchange]<br/>컴포넌트에서 입력값이 변경된 후 포커스가 해제될때 발생합니다.",
    "validation" : [
        "컴포넌트에서 입력값이 변경된 후 포커스가 해제될때 발생합니다.",
        "스크립트에서 setValue() 메소드로 입력값을 변경한 경우 포커스에 관계없이 onchange 이벤트가 발생합니다.",
        "info 파라미터로 변경된 입력값에 대한 정보가 객체로 전달됩니다.",
        "info.oldValue 속성으로 변경되기 전 입력값을 문자열로 갖습니다.",
        "info.newValue 속성으로 변경된 후 입력값을 문자열로 갖습니다.",
        "입력값에 변경이 없으면 onchange 이벤트는 발생하지 않습니다.",
        "enterBlur 속성값에 관계없이 입력값이 변경된 상태로 Enter 키 입력 시 onchange 이벤트가 발생합니다.",
        "ref 속성으로 DataCollection 을 바인딩 한 경우 데이터 선택에 의해 다른 값으로 변경되면 onchange 이벤트가 발생합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        ref: wf_sample.getObj("con_ref").getText(),
        enterBlur: wf_sample.getObj("con_enterBlur").getText(),
        style: 'width:200px;height:30px',
    };

    let cList = $c.gcm.createCList(properties);    
    let eList = $c.gcm.createEList(["onchange"]);

    $c.gcm.createEmptyInput(cList, eList);
}
